// 原逻辑
if (!allObserved) {
    e.global_epoch.store(current + 1, release);  // 空转
    return;
}
// 回收 epoch < current 的节点，但 current=0，所有节点 epoch=0
// epoch < 0 永远为空

// 每次 retire 分配一个新 epoch
uint64_t epoch = e.global_epoch.fetch_add(1, relaxed);
retired_.push_back({node, epoch});

// 找所有活跃线程中最小的 epoch
uint64_t minEpoch = UINT64_MAX;
for (auto& t : e.threads) {
    if (t.active.load(acquire)) {
        minEpoch = min(minEpoch, t.epoch.load(acquire));
    }
}
// 回收所有 epoch < minEpoch 的节点
for (auto& r : retired_) {
    if (r.epoch < minEpoch) delete r.node;
}

struct EbrGuard {
    EbrGuard()  { enterThread(); }
    ~EbrGuard() { leaveThread(); }
};

SkipListNode* insert(...) {
    EbrGuard guard;  // 每次操作自动刷新 epoch
    ...
}
